async function resizeImageData(file){if(!file)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Ảnh cần là JPEG, PNG hoặc WebP');if(file.size>8_000_000)throw Error('Ảnh gốc tối đa 8 MB');const img=new Image(),url=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas'),scale=Math.min(1,320/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let value=canvas.toDataURL('image/jpeg',.72);if(value.length>43700)value=canvas.toDataURL('image/jpeg',.5);if(value.length>43700)throw Error('Ảnh vẫn quá lớn sau khi nén, hãy chọn ảnh khác');return value}finally{URL.revokeObjectURL(url)}}
